const rawData = $input.first().json;
const data = Array.isArray(rawData) ? rawData : [];
// Skip first item (legal disclaimer)
const jobs = data.slice(1);

return jobs
  .filter(job => job && job.position)
  .map(job => ({
    json: {
      job_title: job.position || '',
      company: job.company || '',
      job_url: job.url || `https://remoteok.com/remote-jobs/${job.id}`,
      source: 'Remote OK',
      location_text: job.location || 'worldwide',
      salary: job.salary || '',
      description: [
        job.description || '',
        'Tags: ' + (Array.isArray(job.tags) ? job.tags.join(', ') : '')
      ].join(' '),
      posted_date: job.date || new Date().toISOString().split('T')[0],
      tags: Array.isArray(job.tags) ? job.tags.join(', ') : '',
      job_id: 'remoteok_' + (job.id || Math.random().toString(36).slice(2))
    }
  }));

const data = $input.first().json;
const jobs = (data && Array.isArray(data.jobs)) ? data.jobs : [];

return jobs
  .filter(job => job && job.title)
  .map(job => ({
    json: {
      job_title: job.title || '',
      company: job.company_name || '',
      job_url: job.url || '',
      source: 'Remotive',
      location_text: job.candidate_required_location || 'Worldwide',
      salary: job.salary || '',
      description: job.description || '',
      posted_date: job.publication_date || new Date().toISOString().split('T')[0],
      tags: Array.isArray(job.tags) ? job.tags.join(', ') : '',
      job_id: 'remotive_' + (job.id || Math.random().toString(36).slice(2))
    }
  }));

const items = $input.all();

return items
  .map(item => {
    const d = item.json;
    const title = d.title || '';
    // WWR format: "Job Title at Company [in Category]"
    const atIdx = title.lastIndexOf(' at ');
    const jobTitle = atIdx > -1 ? title.substring(0, atIdx).trim() : title;
    const afterAt = atIdx > -1 ? title.substring(atIdx + 4).trim() : '';
    const company = afterAt.split(' [')[0].trim();

    return {
      json: {
        job_title: jobTitle,
        company: company,
        job_url: d.link || d.guid || '',
        source: 'We Work Remotely',
        location_text: 'remote',
        salary: '',
        description: d.content || d.contentSnippet || d.summary || '',
        posted_date: d.isoDate ? d.isoDate.split('T')[0] : new Date().toISOString().split('T')[0],
        tags: '',
        job_id: 'wwr_' + (d.link || '').replace(/[^a-zA-Z0-9]/g, '').slice(-20)
      }
    };
  })
  .filter(j => j.json.job_title);

// Himalayas RSS feed items
const items = $input.all();

return items
  .map(item => {
    const d = item.json;
    const title = d.title || '';
    // Extract company from title if possible
    const atIdx = title.lastIndexOf(' at ');
    const jobTitle = atIdx > -1 ? title.substring(0, atIdx).trim() : title;
    const company = atIdx > -1 ? title.substring(atIdx + 4).trim() : (d.author || '');

    return {
      json: {
        job_title: jobTitle || d.title || '',
        company: company,
        job_url: d.link || d.guid || '',
        source: 'Himalayas',
        location_text: 'worldwide',
        salary: '',
        description: d.content || d.contentSnippet || d.summary || '',
        posted_date: d.isoDate ? d.isoDate.split('T')[0] : new Date().toISOString().split('T')[0],
        tags: '',
        job_id: 'himalayas_' + (d.link || '').replace(/[^a-zA-Z0-9]/g, '').slice(-20)
      }
    };
  })
  .filter(j => j.json.job_title);

const items = $input.all();

return items
  .map(item => {
    const d = item.json;
    const title = d.title || '';
    const atIdx = title.lastIndexOf(' at ');
    const jobTitle = atIdx > -1 ? title.substring(0, atIdx).trim() : title;
    const company = atIdx > -1 ? title.substring(atIdx + 4).trim() : '';

    return {
      json: {
        job_title: jobTitle || title,
        company: company,
        job_url: d.link || d.guid || '',
        source: 'Dynamite Jobs',
        location_text: 'remote',
        salary: '',
        description: d.content || d.contentSnippet || d.summary || '',
        posted_date: d.isoDate ? d.isoDate.split('T')[0] : new Date().toISOString().split('T')[0],
        tags: '',
        job_id: 'dynamite_' + (d.link || '').replace(/[^a-zA-Z0-9]/g, '').slice(-20)
      }
    };
  })
  .filter(j => j.json.job_title);

// Wellfound returns HTML — extract job links with basic parsing
// NOTE: Wellfound may require login or anti-bot bypass; results may be empty
const rawHtml = String($input.first().json?.body || $input.first().json?.data || '');

if (!rawHtml || rawHtml.length < 100) {
  // Return empty if we can't get content
  return [];
}

// Basic extraction: find job title patterns in HTML
const jobMatches = [...rawHtml.matchAll(/data-test="StartupResult"[^>]*>.*?<a[^>]+href="(\/jobs\/[^"]+)"[^>]*>([^<]+)<\/a>/gs)];

if (jobMatches.length === 0) {
  return [];
}

return jobMatches.slice(0, 50).map((m, i) => ({
  json: {
    job_title: (m[2] || '').trim(),
    company: '',
    job_url: 'https://wellfound.com' + (m[1] || ''),
    source: 'Wellfound',
    location_text: 'remote',
    salary: '',
    description: (m[2] || '') + ' remote startup role',
    posted_date: new Date().toISOString().split('T')[0],
    tags: '',
    job_id: 'wellfound_' + (m[1] || i).toString().replace(/[^a-zA-Z0-9]/g, '').slice(-20)
  }
})).filter(j => j.json.job_title);

// YC Work at a Startup returns HTML
// NOTE: May require session cookie; results may be partial
const rawHtml = String($input.first().json?.body || $input.first().json?.data || '');

if (!rawHtml || rawHtml.length < 100) {
  return [];
}

// Try to extract job data from JSON embedded in page
const jsonMatch = rawHtml.match(/window\.__remixContext\s*=\s*(\{.+?\});/s) ||
                  rawHtml.match(/<script[^>]*type="application\/json"[^>]*>(.+?)<\/script>/s);

if (jsonMatch) {
  try {
    const pageData = JSON.parse(jsonMatch[1]);
    const jobs = pageData?.state?.loaderData?.root?.jobs || 
                 pageData?.jobs || [];
    if (Array.isArray(jobs) && jobs.length > 0) {
      return jobs.slice(0, 50).map(job => ({
        json: {
          job_title: job.title || job.role || '',
          company: job.company?.name || job.companyName || '',
          job_url: `https://www.workatastartup.com/jobs/${job.id || ''}`,
          source: 'YC Work at a Startup',
          location_text: job.locationTag || 'remote',
          salary: job.minExperience ? '' : '',
          description: [job.description || '', job.locationTag || ''].join(' '),
          posted_date: new Date().toISOString().split('T')[0],
          tags: '',
          job_id: 'yc_' + (job.id || Math.random().toString(36).slice(2))
        }
      })).filter(j => j.json.job_title);
    }
  } catch (e) {}
}

return [];

// Otta returns HTML or JSON
// NOTE: Otta is SPA-heavy; results may require API auth
const raw = $input.first().json;
const rawStr = String(raw?.body || raw?.data || JSON.stringify(raw) || '');

if (!rawStr || rawStr.length < 50) {
  return [];
}

// Try JSON response first
if (raw && Array.isArray(raw.jobs)) {
  return raw.jobs.slice(0, 50).map(job => ({
    json: {
      job_title: job.title || '',
      company: job.company?.name || '',
      job_url: `https://app.otta.com/jobs/${job.slug || job.id || ''}`,
      source: 'Otta',
      location_text: job.remote ? 'remote' : (job.locations || []).join(', '),
      salary: job.minAnnualSalary ? `${job.minAnnualSalary}-${job.maxAnnualSalary}` : '',
      description: job.description || '',
      posted_date: new Date().toISOString().split('T')[0],
      tags: (job.tags || []).join(', '),
      job_id: 'otta_' + (job.id || Math.random().toString(36).slice(2))
    }
  })).filter(j => j.json.job_title);
}

return [];

const TITLE_KEYWORDS = [
  'data analyst', 'data scientist', 'business intelligence', 'bi analyst',
  'marketing analyst', 'growth analyst', 'growth hacker', 'performance marketing',
  'ai marketing', 'ai automation', 'ai workflow', 'automation specialist',
  'marketing operations', 'martech', 'analytics engineer', 'data engineer',
  'product analyst', 'revenue analyst', 'crm analyst', 'seo analyst',
  'ppc analyst', 'digital marketing analyst', 'insights analyst',
  'reporting analyst', 'creative strategist'
];

const LOCATION_PASS = [
  'worldwide', 'global', 'anywhere', 'international', 'remote', 'apac',
  'asia', 'wfh', 'distributed'
];

const LOCATION_FAIL = [
  'us only', 'usa only', 'united states only', 'canada only', 'uk only',
  'eu only', 'europe only', 'australia only', 'germany only', 'france only'
];

const items = $input.all();
return items.filter(item => {
  const title = (item.json.job_title || '').toLowerCase();
  const desc = (item.json.description || '').toLowerCase();
  const loc = (item.json.location_text || '').toLowerCase();
  const combined = title + ' ' + desc + ' ' + loc;

  // Hard reject certain location-locked jobs early
  const locFail = LOCATION_FAIL.some(kw => loc.includes(kw));
  if (locFail) return false;

  // Accept if title matches role keywords
  const titleMatch = TITLE_KEYWORDS.some(kw => title.includes(kw));
  if (titleMatch) return true;

  // Accept if description or tags mention async/global keywords
  const descKeywords = [
    'async', 'asynchronous', 'work from anywhere', 'worldwide remote',
    'global remote', 'distributed team', 'remote first', 'flexible hours',
    'work across time zones'
  ];
  return descKeywords.some(kw => combined.includes(kw));
});

const REJECT_PHRASES = [
  'us only', 'usa only', 'united states only', 'us residents only',
  'canada only', 'canadian residents', 'uk only', 'united kingdom only',
  'eu only', 'eu residents', 'europe only', 'european union only',
  'australia only', 'australian residents',
  'must be based in', 'must live in', 'must reside in',
  'must be authorized to work in', 'must have work authorization',
  'local work permit required', 'right to work in',
  'authorized to work in the us', 'authorized to work in the uk',
  'authorized to work in canada', 'authorized to work in australia',
  'hybrid', 'onsite', 'on-site', 'on site', 'office required',
  'in-office', 'in office',
  'remote within country only', 'remote within the us', 'remote within us',
  'fixed us hours', 'fixed est hours', 'fixed pst hours',
  'fixed cet hours', 'fixed gmt hours',
  'no international', 'no overseas', 'domestic only',
  'must overlap 9-5 est', 'must overlap 9-5 pst', 'full overlap with us',
  'not available in', 'unavailable in taiwan'
];

const KEEP_PHRASES = [
  'worldwide', 'work from anywhere', 'global remote', 'wfa',
  'apac', 'international contractors', 'international contractor',
  'contractor role', 'b2b contractor', 'hire via deel', 'hires via deel',
  'hire via remote.com', 'hires via remote.com', 'hire via oyster',
  'hires via oyster', 'eor', 'employer of record', 'remote first',
  'distributed team', 'fully distributed', 'all remote',
  'open to all countries', 'open to any country', 'global team',
  'no location restrictions', 'any timezone', 'all timezones'
];

const items = $input.all();
return items.filter(item => {
  const text = [
    item.json.job_title || '',
    item.json.description || '',
    item.json.location_text || '',
    item.json.tags || ''
  ].join(' ').toLowerCase();

  // Hard reject if reject phrase found
  const rejected = REJECT_PHRASES.some(phrase => text.includes(phrase));
  if (rejected) return false;

  // Always keep if explicit global/WFA signal
  const kept = KEEP_PHRASES.some(phrase => text.includes(phrase));
  if (kept) return true;

  // Otherwise keep for AI to decide (unclear cases)
  return true;
}).map(item => ({
  ...item,
  json: {
    ...item.json,
    hard_filter_passed: true,
    hard_filter_date: new Date().toISOString().split('T')[0]
  }
}));

// Use workflow static data for persistence across runs
const staticData = $getWorkflowStaticData('global');
if (!staticData.seenUrls) staticData.seenUrls = {};
if (!staticData.seenKeys) staticData.seenKeys = {};

const items = $input.all();
const newItems = [];
const today = new Date().toISOString().split('T')[0];

for (const item of items) {
  const url = (item.json.job_url || '').trim();
  const key = ((item.json.company || '') + '_' + (item.json.job_title || '')).toLowerCase().replace(/\s+/g, '_');

  if (!url && !key) continue;

  const urlSeen = url && staticData.seenUrls[url];
  const keySeen = key && staticData.seenKeys[key];

  if (!urlSeen && !keySeen) {
    if (url) staticData.seenUrls[url] = today;
    if (key) staticData.seenKeys[key] = today;
    newItems.push(item);
  }
}

// Prune old entries (keep last 30 days)
const cutoff = new Date();
cutoff.setDate(cutoff.getDate() - 30);
const cutoffStr = cutoff.toISOString().split('T')[0];

for (const [k, v] of Object.entries(staticData.seenUrls)) {
  if (v < cutoffStr) delete staticData.seenUrls[k];
}
for (const [k, v] of Object.entries(staticData.seenKeys)) {
  if (v < cutoffStr) delete staticData.seenKeys[k];
}

return newItems;

const job = $input.first().json;

const prompt = `You are filtering remote jobs for Jerry, who lives in Taiwan.

The most important rule:
Jerry must be able to work this job while physically based in Taiwan.

Do not pass the job only because it says "remote."

Reject the job if it requires the worker to live in the US, Canada, UK, EU, Europe, Australia, or any specific country outside Taiwan.
Reject the job if it requires local work authorization outside Taiwan.
Reject the job if it is hybrid, onsite, or remote within one country only.
Reject the job if it requires fixed working hours that would force Jerry to work through the night in Taiwan (e.g. fixed EST, PST, CET hours).

Keep the job only if one of these is true:
- The job says worldwide remote
- The job says work from anywhere
- The job says global remote
- The job says APAC remote
- The job allows international contractors
- The job accepts people based anywhere
- The company hires through EOR, Deel, Remote.com, Oyster, or contractor agreement

Job Title: ${job.job_title}
Company: ${job.company}
Location Text: ${job.location_text}
Salary: ${job.salary || 'Not listed'}
Tags: ${job.tags || 'None'}

Job Description (first 2000 chars):
${(job.description || '').substring(0, 2000)}

Return ONLY valid JSON, no markdown, no explanation:
{
  "taiwan_eligible": "yes/no/unclear",
  "reason": "one sentence reason",
  "location_risk": "low/medium/high",
  "timezone_risk": "low/medium/high",
  "contractor_possible": "yes/no/unclear",
  "decision": "keep/reject/manual_check"
}`;

return [{
  json: {
    ...job,
    ai_prompt: prompt
  }
}];

const aiResp = $input.first().json;
const prevJob = $('Build AI Prompt').first().json;

// Parse AI response
let aiData = { taiwan_eligible: 'unclear', reason: '', location_risk: 'medium', timezone_risk: 'medium', contractor_possible: 'unclear', decision: 'manual_check' };
try {
  const rawText = (aiResp?.content?.[0]?.text || '').trim();
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  if (jsonMatch) aiData = { ...aiData, ...JSON.parse(jsonMatch[0]) };
} catch (e) {
  aiData.reason = 'Failed to parse AI response';
}

// === SCORING SYSTEM ===
let score = 0;
const desc = (prevJob.description || '').toLowerCase();
const loc = (prevJob.location_text || '').toLowerCase();
const title = (prevJob.job_title || '').toLowerCase();

// Taiwan Eligibility (0–40 pts)
if (aiData.taiwan_eligible === 'yes' && aiData.location_risk === 'low') {
  score += 40;
} else if (aiData.taiwan_eligible === 'yes') {
  const globalPhrases = ['worldwide', 'work from anywhere', 'global remote', 'wfa', 'international contractor', 'apac'];
  const isGlobal = globalPhrases.some(p => desc.includes(p) || loc.includes(p));
  score += isGlobal ? 40 : 30;
} else if (aiData.taiwan_eligible === 'unclear') {
  if (aiData.location_risk === 'low') score += 30;
  else if (aiData.location_risk === 'medium') score += 20;
  else score += 5;
} else {
  score += 0; // taiwan_eligible === 'no'
}

// Async Fit (0–25 pts)
const asyncPhrases = [
  { phrase: 'async', pts: 25 }, { phrase: 'asynchronous', pts: 25 },
  { phrase: 'flexible hours', pts: 20 }, { phrase: 'flexible schedule', pts: 20 },
  { phrase: 'no meetings', pts: 20 }, { phrase: 'low meeting', pts: 20 },
  { phrase: 'distributed team', pts: 15 }, { phrase: 'fully distributed', pts: 15 },
  { phrase: 'remote first', pts: 10 }, { phrase: 'remote-first', pts: 10 },
  { phrase: 'work across time zones', pts: 15 }, { phrase: 'across timezones', pts: 15 }
];
const asyncScore = asyncPhrases.reduce((best, p) => desc.includes(p.phrase) ? Math.max(best, p.pts) : best, 0);
score += asyncScore;

// Reject phrases for async
const asyncRejectPhrases = ['strict 9 to 5', 'fixed us hours', 'fixed est', 'fixed pst', 'fixed cet', 'daily live calls required', 'must overlap full business day'];
const asyncRejected = asyncRejectPhrases.some(p => desc.includes(p));
if (asyncRejected) score -= 20;

// Role Fit (0–25 pts)
const roleTiers = [
  { keywords: ['data analyst', 'data scientist', 'business intelligence', 'bi analyst', 'marketing analyst', 'growth analyst', 'ai marketing', 'ai automation', 'performance marketing', 'marketing operations', 'martech analyst', 'analytics engineer', 'automation specialist', 'ai workflow'], pts: 25 },
  { keywords: ['product analyst', 'revenue analyst', 'seo analyst', 'ppc analyst', 'digital marketing', 'crm analyst', 'insights analyst', 'reporting analyst', 'creative strategist', 'growth hacker', 'data engineer'], pts: 15 }
];
const roleScore = roleTiers.reduce((best, tier) => {
  const match = tier.keywords.some(kw => title.includes(kw));
  return match ? Math.max(best, tier.pts) : best;
}, 0);
score += roleScore;

// Salary Fit (0–25 pts)
const salaryText = (prevJob.salary || '').toLowerCase();
const salaryNums = salaryText.match(/\d[\d,]+/g)?.map(n => parseInt(n.replace(/,/g, ''))) || [];
const maxSalary = salaryNums.length > 0 ? Math.max(...salaryNums) : 0;
if (maxSalary >= 5000) score += 25;
else if (maxSalary >= 3000) score += 15;
else if (salaryText.length > 0) score += 10;

// Async level label
let asyncLevel = 'unknown';
if (asyncScore >= 20) asyncLevel = 'high';
else if (asyncScore >= 10) asyncLevel = 'medium';
else if (asyncScore > 0) asyncLevel = 'low';
else asyncLevel = 'not mentioned';

// Role category
let roleCategory = 'other';
if (roleTiers[0].keywords.some(kw => title.includes(kw))) roleCategory = 'core fit';
else if (roleTiers[1].keywords.some(kw => title.includes(kw))) roleCategory = 'adjacent fit';

// Why good fit
const reasons = [];
if (aiData.taiwan_eligible === 'yes') reasons.push('Taiwan eligible: ' + aiData.reason);
if (asyncLevel === 'high') reasons.push('Fully async or flexible schedule');
if (roleCategory === 'core fit') reasons.push('Direct match for Jerry\'s data/analytics/AI marketing background');
if (maxSalary >= 5000) reasons.push(`Strong salary: $${maxSalary}/mo or similar`);
if (aiData.contractor_possible === 'yes') reasons.push('Contractor engagement possible (Deel/Remote/Oyster friendly)');
const whyFit = reasons.join('. ') || 'Review manually';

return [{
  json: {
    ...prevJob,
    taiwan_eligible: aiData.taiwan_eligible,
    taiwan_reason: aiData.reason,
    location_risk: aiData.location_risk,
    timezone_risk: aiData.timezone_risk,
    contractor_possible: aiData.contractor_possible,
    ai_decision: aiData.decision,
    async_level: asyncLevel,
    role_category: roleCategory,
    why_good_fit: whyFit,
    score: Math.max(0, Math.min(100, score)),
    date_found: new Date().toISOString().split('T')[0],
    application_status: 'new',
    notes: ''
  }
}];

const today = new Date().toISOString().split('T')[0];
const allJobs = $input.all().map(i => i.json);

// Filter to today's jobs
const todayJobs = allJobs.filter(j => j.date_found === today);

// Sort by score descending
todayJobs.sort((a, b) => (parseInt(b.score) || 0) - (parseInt(a.score) || 0));

const topJobs = todayJobs.filter(j => j.taiwan_eligible !== 'no').slice(0, 10);
const manualJobs = todayJobs.filter(j => j.taiwan_eligible === 'unclear' && (parseInt(j.score) || 0) >= 70);

if (topJobs.length === 0) {
  return [{
    json: {
      subject: `Daily Taiwan Async Jobs – ${today} – No new matches`,
      htmlBody: `<h2>Daily Taiwan Eligible Async Remote Jobs</h2><p>No new jobs found today matching your criteria. Will check again tomorrow.</p>`,
      jobCount: 0
    }
  }];
}

// Build HTML digest
let html = `<h1>🌏 Daily Taiwan Eligible Async Remote Jobs</h1>`;
html += `<p><strong>Date:</strong> ${today} | <strong>New matches:</strong> ${topJobs.length}</p>`;
html += `<hr/>`;

topJobs.forEach((job, i) => {
  const scoreEmoji = parseInt(job.score) >= 85 ? '🔥' : parseInt(job.score) >= 75 ? '⭐' : '✅';
  html += `<h2>${scoreEmoji} ${i + 1}. ${job.job_title}</h2>`;
  html += `<p><strong>Company:</strong> ${job.company}</p>`;
  html += `<p><strong>Score:</strong> ${job.score}/100</p>`;
  html += `<p><strong>Taiwan Eligible:</strong> ${job.taiwan_eligible}</p>`;
  html += `<p><strong>Reason:</strong> ${job.taiwan_reason}</p>`;
  html += `<p><strong>Async Level:</strong> ${job.async_level}</p>`;
  html += `<p><strong>Timezone Risk:</strong> ${job.timezone_risk}</p>`;
  html += `<p><strong>Salary:</strong> ${job.salary || 'Not listed'}</p>`;
  html += `<p><strong>Why it fits Jerry:</strong> ${job.why_good_fit}</p>`;
  html += `<p><a href="${job.job_url}">👉 Apply Here</a></p><hr/>`;
});

if (manualJobs.length > 0) {
  html += `<h2>🔍 Manual Review Needed (unclear eligibility, high score)</h2><ul>`;
  manualJobs.forEach(j => {
    html += `<li><a href="${j.job_url}">${j.job_title} at ${j.company}</a> — Score: ${j.score} | ${j.taiwan_reason}</li>`;
  });
  html += `</ul><hr/>`;
}

// Rejection summary
const allRejectedToday = allJobs.filter(j => j.date_found === today && j.taiwan_eligible === 'no');
const usOnly = allRejectedToday.filter(j => (j.taiwan_reason || '').toLowerCase().includes('us')).length;
const euOnly = allRejectedToday.filter(j => (j.taiwan_reason || '').toLowerCase().includes('eu') || (j.taiwan_reason || '').toLowerCase().includes('europe')).length;
const hybrid = allRejectedToday.filter(j => (j.taiwan_reason || '').toLowerCase().includes('hybrid')).length;
const timezone = allRejectedToday.filter(j => (j.taiwan_reason || '').toLowerCase().includes('timezone') || (j.taiwan_reason || '').toLowerCase().includes('hours')).length;

html += `<h2>📊 Rejected Today (${allRejectedToday.length} jobs)</h2>`;
html += `<ul>`;
html += `<li>US only: ${usOnly}</li>`;
html += `<li>EU only: ${euOnly}</li>`;
html += `<li>Hybrid/Onsite: ${hybrid}</li>`;
html += `<li>Timezone conflict: ${timezone}</li>`;
html += `<li>Other/Low score: ${allRejectedToday.length - usOnly - euOnly - hybrid - timezone}</li>`;
html += `</ul>`;

return [{
  json: {
    subject: `🌏 Daily Taiwan Async Jobs – ${today} – ${topJobs.length} matches found`,
    htmlBody: html,
    jobCount: topJobs.length,
    topScore: topJobs[0]?.score || 0
  }
}];
